contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 tokensToBuy) public payable {
        require(tokensToBuy >= 0);

        bool finishReverted;
        c.finishDistribution(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { finishReverted = true; } else { finishReverted = false; }

        bool getTokensReverted;
        c.getTokens(); bool __rev1 = __ESBMC_reverted(); if (__rev1) { getTokensReverted = true; } else { getTokensReverted = false; }

        assert(!(finishReverted == false && c.distributionFinished() == true && getTokensReverted == false));
    }

    receive() external payable {}
}

