pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    NewIntelTechMedia c;

    function setUp() public {
        c = new NewIntelTechMedia();
    }

    function _run(uint256 tokensToBuy) internal {
        vm.assume(tokensToBuy >= 0);
        bool finishReverted;
        try c.finishDistribution() { finishReverted = false; } catch { finishReverted = true; }
        bool getTokensReverted;
        try c.getTokens() { getTokensReverted = false; } catch { getTokensReverted = true; }
        assertTrue(!(finishReverted == false && c.distributionFinished() == true && getTokensReverted == false));
    }

    function testFuzz_run(uint256 tokensToBuy) public {
        _run(tokensToBuy);
    }

    receive() external payable {}
}
